// Extract message data from Telegram webhook payload
const message = $input.first().json.message;

const chatId = message.chat.id;
const userId = message.from.id;
const username = message.from.username || '';
const firstName = message.from.first_name || '';
const lastName = message.from.last_name || '';
const messageText = message.text || '';
const messageId = message.message_id;
const timestamp = new Date(message.date * 1000).toISOString();

// Detect if this is a command
const isCommand = messageText.startsWith('/');
const command = isCommand ? messageText.split(' ')[0] : null;
const commandArgs = isCommand ? messageText.substring(command.length).trim() : null;

return [{
  json: {
    chatId,
    userId: userId.toString(),
    username,
    firstName,
    lastName,
    fullName: `${firstName} ${lastName}`.trim(),
    messageText,
    messageId,
    timestamp,
    isCommand,
    command,
    commandArgs,
    platform: 'telegram'
  }
}];

// Build conversation context for the AI agent
const messageData = $('Extract Message Data').item.json;
const clientData = $('Authenticate Client').item.json[0];
const conversationData = $input.first().json;

// Extract recent messages for context (last 20)
let recentMessages = [];
if (Array.isArray(conversationData) && conversationData.length > 0) {
  const conv = conversationData[0];
  if (conv.messages && Array.isArray(conv.messages)) {
    recentMessages = conv.messages.slice(-20);
  }
}

const systemPrompt = `You are an AI assistant for ${clientData.company || clientData.name}. You help users via Telegram.

User info:
- Name: ${messageData.fullName}
- Username: @${messageData.username}
- Platform: Telegram

Client plan: ${clientData.plan}
Available commands: ${(clientData.allowed_commands || []).join(', ') || 'none configured'}

Guidelines:
- Be helpful, concise, and professional
- If the user asks for a file, use the file search tool
- If you cannot fulfill a request, explain why clearly
- Keep responses under 4096 characters (Telegram limit)`;

return [{
  json: {
    systemPrompt,
    userMessage: messageData.messageText,
    recentMessages,
    conversationId: (Array.isArray(conversationData) && conversationData.length > 0) ? conversationData[0].id : null,
    clientId: clientData.id,
    chatId: messageData.chatId,
    userId: messageData.userId,
    username: messageData.username
  }
}];

// File search tool - searches configured directory for matching files
const query = $input.first().json.query || $input.first().json.input || '';
const searchDir = $env.CLIENT_FILES_DIR || '/data/client-files';

// This is a placeholder - in production, query Supabase Storage or local filesystem
const result = {
  query: query,
  searchDir: searchDir,
  message: `Searched for "${query}" in client files directory. Configure CLIENT_FILES_DIR env var and implement actual file search logic.`,
  files: []
};

return [{ json: result }];

// Format the AI response for Telegram
const aiOutput = $input.first().json.output || $input.first().json.text || 'Sorry, I could not generate a response.';
const contextData = $('Build AI Context').item.json;

// Telegram message limit is 4096 characters
let responseText = aiOutput;
if (responseText.length > 4096) {
  responseText = responseText.substring(0, 4090) + '\n...';
}

return [{
  json: {
    chatId: contextData.chatId,
    responseText: responseText,
    conversationId: contextData.conversationId,
    clientId: contextData.clientId,
    userId: contextData.userId,
    userMessage: contextData.userMessage,
    aiResponse: aiOutput
  }
}];
